CREATE     PROCEDURE [synapse_fo].[usp_Insert_RETAILINVENTTABLE]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:29:58
	Description: Insert stored procedure for RETAILINVENTTABLE from synapse finops datalake to BI
*/
BEGIN
	INSERT INTO [synapse_fo].[RETAILINVENTTABLE]
	(
		[BARCODESETUPID],
		[BASECOMPARISONUNITCODE],
		[BLOCKEDONPOS],
		[DATAAREAID],
		[DataLakeModified_DateTime],
		[DATEBLOCKED],
		[DATETOACTIVATEITEM],
		[DATETOBEBLOCKED],
		--[FileName],
		[ITEMID],
		[KEYINGINPRICE],
		[KEYINGINQTY],
		[LABELATTRIBUTE1],
		[LABELATTRIBUTE2],
		[LABELATTRIBUTE3],
		[LABELATTRIBUTE4],
		[LABELATTRIBUTE5],
		[LastProcessedChange_DateTime],
		[LIFEFROM],
		[LIFETO],
		--[LSN],
		[MUSTKEYINCOMMENT],
		[NODISCOUNTALLOWED],
		[NOMANUALDISCOUNTALLOWED],
		[NOPERIODICDISCOUNTALLOWED],
		[NOTENDERDISCOUNTSALLOWED],
		[PARTITION],
		[PRINTVARIANTSSHELFLABELS],
		[PROHIBITRETURN_RU],
		[QTYBECOMESNEGATIVE],
		[RECID],
		[RECVERSION],
		[SCALEITEM],
		[SEASONCODE],
		--[SysRowId],
		[USEEANSTANDARDBARCODE],
		[ZEROPRICEVALID]
	)
	SELECT 
		stg.[BARCODESETUPID],
		stg.[BASECOMPARISONUNITCODE],
		stg.[BLOCKEDONPOS],
		stg.[DATAAREAID],
		stg.[DataLakeModified_DateTime],
		stg.[DATEBLOCKED],
		stg.[DATETOACTIVATEITEM],
		stg.[DATETOBEBLOCKED],
		--stg.--[FileName],
		stg.[ITEMID],
		stg.[KEYINGINPRICE],
		stg.[KEYINGINQTY],
		stg.[LABELATTRIBUTE1],
		stg.[LABELATTRIBUTE2],
		stg.[LABELATTRIBUTE3],
		stg.[LABELATTRIBUTE4],
		stg.[LABELATTRIBUTE5],
		stg.[LastProcessedChange_DateTime],
		stg.[LIFEFROM],
		stg.[LIFETO],
		--stg.--[LSN],
		stg.[MUSTKEYINCOMMENT],
		stg.[NODISCOUNTALLOWED],
		stg.[NOMANUALDISCOUNTALLOWED],
		stg.[NOPERIODICDISCOUNTALLOWED],
		stg.[NOTENDERDISCOUNTSALLOWED],
		stg.[PARTITION],
		stg.[PRINTVARIANTSSHELFLABELS],
		stg.[PROHIBITRETURN_RU],
		stg.[QTYBECOMESNEGATIVE],
		stg.[RECID],
		stg.[RECVERSION],
		stg.[SCALEITEM],
		stg.[SEASONCODE],
		--stg.--[SysRowId],
		stg.[USEEANSTANDARDBARCODE],
		stg.[ZEROPRICEVALID]	
	FROM [staging_fo].[RETAILINVENTTABLE] stg
		LEFT JOIN [synapse_fo].[RETAILINVENTTABLE] tgt
			ON stg.[DataAreaId] = tgt.[DataAreaId] 
			AND stg.[itemId] = tgt.[itemId] 
			AND stg.[PARTITION] = tgt.[PARTITION] 
		
	WHERE tgt.[RECID] IS NULL
END
